-- RC-1130 (RP-141): the runs a fine-tuning use case pins or excludes for its next builds, behind
-- FF_FINE_TUNING. Same meaning as `pinned` and `excluded_at` of `task_eval_cases`: an exclusion
-- stays, so a later build cannot select the run again. Generated by drizzle-kit from
-- views/fine-tuning/schema.ts, then written as upstream's 0114 (ratel-cloud): IF NOT EXISTS, with
-- the foreign key inline, so a database migrated by ratel-cloud already has it and this is a no-op
-- there. A new, empty table: no lock on a hot table, nothing to backfill.
CREATE TABLE IF NOT EXISTS "fine_tuning_use_case_overrides" (
	"use_case_id" uuid NOT NULL,
	"turn_id" uuid NOT NULL,
	"pinned" boolean DEFAULT false NOT NULL,
	"excluded_at" timestamp with time zone,
	"set_by" text NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "fine_tuning_use_case_overrides_use_case_id_turn_id_pk" PRIMARY KEY("use_case_id","turn_id"),
	CONSTRAINT "fine_tuning_use_case_overrides_use_case_id_fine_tuning_use_cases_id_fk" FOREIGN KEY ("use_case_id") REFERENCES "public"."fine_tuning_use_cases"("id") ON DELETE cascade ON UPDATE no action
);
